        "rule_leaves_body": "Unlinking clears their account and deactivates every agent token they hold in this workspace. Their comments, PRs and logged hours stay on the tasks, attributed to them. Nothing is deleted.",
        "rule_leaves_where": "Modules/Agents/accounts.js — unlink sets active false on their agent tokens and unsets agentAccount",
        "rule_lapses": "Their subscription lapses.",
        "rule_lapses_body": "A personal-mode CLI fails on their machine, and AlianHub never sees it: a CLI session creates no run record, so the task simply stays assigned to them with no new activity. Workspace-mode runs do record a failed status with the reason.",
        "rule_lapses_where": "Modules/Agents/runs.js — a failed status is written by the server-side run engine only",
        "rule_contractor": "A contractor wants their own account.",
        "rule_contractor_body": "Allowed, but their token can be scoped to the projects they are in. Then even the next-task and search tools only return tasks from those projects.",
        "rule_contractor_where": "Modules/Mcp/tools.js — scopeFilter adds the token's projectIds to every tool query",
        "rule_two_people": "Two people, one task.",
        "rule_two_people_body": "Both can run agents on it. Each comment is stamped with the actor type, the agent and the account it came through, so a duplicate PR is obvious rather than mysterious.",
        "rule_two_people_where": "Modules/Agents/actions.js — task.comment stamps actorType, agentId and viaAccount on the comment",
        "rule_require_mode": "An admin can require a mode.",
        "rule_require_mode_body": "A regulated customer allows local only, and linking or minting anything else is refused with the reason shown rather than the option quietly disappearing.",
        "rule_require_mode_where": "Modules/Agents/accounts.js link and Modules/ApiTokens/controller.js createMcpToken both check the policy first",
        "rule_unattended": "Personal accounts cannot run unattended.",
        "rule_unattended_body": "A scheduled run through a personal account is refused, because nobody should be billed for a run they did not trigger while their laptop was shut.",
        "rule_unattended_where": "Modules/Agents/runs.js — canStart refuses a scheduled trigger when the account is personal",
        "rule_allow_list": "The allow-list does not change.",
        "rule_allow_list_body": "A personal account gets exactly the tools listed on the setup panel. The registry decision takes no account mode as an argument, so paying for your own model does not buy extra permissions.",
        "rule_allow_list_where": "Modules/Agents/registry.js — evaluate takes an action key and its params, never a mode",
        "rule_reimbursement": "Reimbursement is a report, not a feature.",
        "rule_reimbursement_body": "AlianHub counts tasks and hours through each person's account from its own rows. It never reads a provider invoice, and has no field to store one.",
        "rule_reimbursement_where": "Modules/Agents/accounts.js — monthlySummary reads timesheet, run and task-link rows only",
        "rule_personal_spend": "Personal spend is never the workspace's.",
        "rule_personal_spend_body": "A run through a personal account records the workspace cost as $0, keeps the estimate separately, and returns before touching the agent's monthly total.",
        "rule_personal_spend_where": "Modules/Agents/runs.js — recordSpend marks the run as not billed to the workspace",
        "rule_local_spend": "Local runs cost the workspace nothing.",
        "rule_local_spend_body": "Self-hosted runs are treated the same way as personal ones for billing: no workspace dollars, and no contribution to a cap.",
        "rule_local_spend_where": "Modules/Agents/runs.js — recordSpend excludes both personal and local from billing",
        "rule_revoke": "Revoking stops future runs and keeps the history.",
        "rule_revoke_body": "Revoke here deactivates the token, so it stops authenticating immediately. Every audit row, comment and time log it already wrote stays exactly where it is.",
        "rule_revoke_where": "Modules/ApiTokens/controller.js — verifyToken only accepts an active token; audit rows live in their own collection",
        "rule_caps": "A cap pauses the agent, it does not fail quietly.",
        "rule_caps_body": "When workspace-billed spend reaches an agent's monthly cap the agent is paused with the reason recorded, and the next run is refused with that same reason.",
        "rule_caps_where": "Modules/Agents/runs.js — recordSpend pauses at the cap and canStart refuses once it is reached",
        "never_title": "Absent from the registry, in every mode",
        "never_source": "LIVE FROM THE MCP MANIFEST",
        "never_body": "These are not permissions that have been switched off. They are not in the action list at all, so a compromised token has nothing to switch on, and an attempt is refused with an audit id.",
        "undecided_title": "Not decided in code yet",
        "undecided_1": "Exporting the monthly summary.",
        "undecided_1_body": "The numbers above are computed on request and there is no export endpoint, so a reimbursement claim is currently a manual read rather than a file.",
        "undecided_2": "Per-person visibility of the full call list.",
        "undecided_2_body": "Every call is audited, but who may read those rows is governed by the existing audit permissions. There is no per-member setting to share or hide the detail.",
        "why_shape_body": "The alternative — the company buys keys for everyone and proxies every call — puts AlianHub in the middle of every prompt a developer writes. That is a privacy problem, a cost problem and a support problem, and developers work around it by using their own CLI outside the tool anyway. Let them keep their own account and their own habits; AlianHub's job is to hand over a good brief and to record what came back."
